<script setup lang="ts">
import { Users,ShieldCheck,Edit3,RefreshCw } from 'lucide-vue-next'
import type {Staff} from '~/types/models'
const {data:staff,error,refresh}=await useFetch<Staff[]>('/api/staff', {key:'staff-list'})
const busy=ref(false);const result=ref('')
const newUser=ref('');const newName=ref('');const newRole=ref<'officer'|'admin'>('officer')
async function createStaff(){result.value='';if(!newUser.value.trim()||!newName.value.trim()){result.value='Vui lòng nhập đầy đủ tên đăng nhập và họ tên.';return}busy.value=true;try{await $fetch('/api/staff',{method:'POST',body:{username:newUser.value.trim(),display_name:newName.value.trim(),role:newRole.value}});result.value='Đã tạo nhân viên mới.';newUser.value='';newName.value='';newRole.value='officer';await refresh();await refreshNuxtData('staff-list')}catch(e){result.value=readableError(e)}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="text-xl font-black">Quản lý nhân viên</h2><p class="text-sm text-muted">Danh sách và tạo tài khoản cán bộ quản trị hệ thống.</p></div></div>
 <div v-if="error" class="panel p-5 text-rose-700">Không tải được danh sách nhân viên. Kiểm tra PostgreSQL và phiên đăng nhập.</div>
 <div class="grid gap-3 md:grid-cols-2"><section class="panel space-y-4 p-5"><h3 class="section-label"><Users :size="20" class="text-brand-600"/>Danh sách nhân viên</h3><div v-if="!staff?.length" class="p-4 text-sm text-muted">Chưa có nhân viên.</div><div v-for="s in staff" :key="s.id" class="flex items-center justify-between gap-3 p-3 rounded-lg border border-[#dae7f7] bg-white"><div class="min-w-0"><p class="text-sm font-bold text-ink">{{s.display_name}}</p><p class="text-xs text-muted">{{s.username}} · {{s.role==='admin'?'Quản trị viên':'Cán bộ xử lý'}}</p></div><span :class="['rounded-full px-2.5 py-0.5 text-[10px] font-bold',s.is_active?'bg-green-100 text-green-700':'bg-rose-100 text-rose-700']">{{s.is_active?'Hoạt động':'Khóa'}}</span></div></section>
 <section class="panel space-y-4 p-5"><h3 class="section-label"><ShieldCheck :size="20" class="text-brand-600"/>Tạo tài khoản mới</h3><form class="space-y-3" @submit.prevent="createStaff"><div><label class="field-label">Tên đăng nhập</label><input v-model="newUser" class="field" required minlength="3" maxlength="50" placeholder="Ví dụ: canbo.demo"/></div><div><label class="field-label">Họ và tên</label><input v-model="newName" class="field" required minlength="2" maxlength="100"/></div><div><label class="field-label">Vai trò</label><select v-model="newRole" class="field"><option value="officer">Cán bộ xử lý</option><option value="admin">Quản trị viên</option></select></div><p v-if="result" class="rounded-lg bg-brand-50 p-3 text-sm text-brand-800">{{result}}</p><button class="btn-primary" :disabled="busy" type="submit"><Edit3 :size="16"/> Tạo tài khoản</button></form></section></div></div></template>
